export interface ChatHistoryItem {
  role: "user" | "assistant" | "system" | "human" | "ai";
  content: string;
}

/**
 * The chat stream is prefixed with a single machine-readable line:
 *   @@SOURCES@@["Case Study AltIndex", ...]\n
 * listing the retrieval sources the answer drew from, followed by the
 * streamed LLM tokens. The list is computed from the retrieval step on the
 * server, never generated by the model.
 */
export const CHAT_SOURCES_MARKER = "@@SOURCES@@";
